INSERT INTO `rfq_requests` VALUES
(1,'RFQ-2073','Sales Abmalaya','sales@abmalaya.com','admin@thwsb.com','Sales Abmalaya',NULL,'Request for Extension of Tender Submission Date – 8308 GCE | Building Works for Gantang Coffee Enterprise Sdn. Bhd.','Dear THW Consultants Sdn. Bhd.,\r\n\r\nGood day and Assalamualaikum W.B.T.\r\n\r\nAttention : @intan@thwsb.com \r\n\r\nWe refer to the above-mentioned tender and respectfully seek your kind\r\nconsideration to extend the tender submission deadline from 3 September\r\n2026 to 10 September 2026.\r\n\r\nFollowing our recent site visit, AB Malaya Sdn. Bhd. has submitted several\r\nRFIs and is currently awaiting the relevant clarifications. Additional time\r\nwould allow our team to properly incorporate the confirmed information and\r\nensure that our tender proposal is comprehensive, accurate, and fully\r\naligned with the project requirements.\r\n\r\nThe recent Maulidur Rasul and National Day public holidays have also\r\nresulted in a shorter working period for tender preparation and\r\ncoordination.\r\n\r\nKindly refer to the attached formal letter for further details and your\r\nconsideration. We sincerely hope this extension can be granted to enable us\r\nto submit the best possible proposal for Gantang Coffee Enterprise Sdn. Bhd.\r\n\r\nWe would appreciate your kind consideration and early confirmation of our\r\nrequest.\r\n\r\nThank you.\r\n\r\nBest regards,\r\nSales\r\nAB Malaya Sdn. Bhd.\r\n\r\n\r\n\n\n\r\nDear THW Consultants Sdn. Bhd.,\n\n\r\nGood day and Assalamualaikum W.B.T.\n\nAttention : @intan@thwsb.com \n\n\r\nWe refer to the above-mentioned tender and respectfully seek your kind consideration to extend the tender submission deadline from 3 September 2026 to 10 September 2026.\n\nFollowing our recent site visit, AB Malaya Sdn. Bhd. has submitted several RFIs and is currently awaiting the relevant clarifications. Additional time would allow our team to properly incorporate the confirmed information and ensure that our tender proposal is comprehensive, accurate, and fully aligned with the project requirements.\n\nThe recent Maulidur Rasul and National Day public holidays have also resulted in a shorter working period for tender preparation and coordination.\n\nKindly refer to the attached formal letter for further details and your consideration. We sincerely hope this extension can be granted to enable us to submit the best possible proposal for Gantang Coffee Enterprise Sdn. Bhd.\n\nWe would appreciate your kind consideration and early confirmation of our request.\n\n\r\n\r\n\r\n\r\n\r\n\n\nThank you.\n\n\r\nBest regards,\n\r\nSales\n\r\nAB Malaya Sdn. Bhd.','None','1 Package',0.00,'http://localhost:8000/api_fetch_live_gmail.php?preview=1&msgno=2073&part=2&ext=pdf&fn=KCG+Baling+-+EOT+tender+No.1.pdf','junk',1,'junk',NULL,'2026-09-01 04:32:37','2026-09-01 07:21:34'),
