(87,'RFQ-1982','noreply@cidb.gov.my','abmalayaindustry@gmail.com','info@abmalaya.com','noreply@cidb.gov.my',NULL,'Notifikasi permohonan daripada CIMS (Application Notification from CIMS)','Tuan,\n\n\nTerima kasih atas permohonan pendaftaran tuan. \n\n\nDilampirkan surat keputusan. Surat tersebut boleh juga diperoleh di portal CIMS.\n\n\nSekian\n\n\nTerima kasih\n\n\nE-mel ini dijana oleh komputer','None','1 Package',0.00,'http://localhost:8000/api_fetch_live_gmail.php?preview=1&msgno=1982&part=2&ext=pdf&fn=STBApprovalLetter_mailcopy_12082026111102.pdf','junk',1,'junk',NULL,'2026-09-01 04:38:52','2026-09-01 08:34:38'),
(88,'RFQ-1981','m2u@maybank.com.my','abmalayaindustry@gmail.com','INFO@abmalaya.com','m2u@maybank.com.my',NULL,'What you need to know before applying for business financing','This email was sent to: INFO@ABMALAYA.COM\n\n  You have received this email because you are a Maybank customer.\n\n To avoid future emails from Maybank being automatically sent to your junk mail folder, we suggest that you add our email address   m2u@maybank.com.my to your Address Book and/or the \"Approved Sender\" list.\n\n  Disclaimer\n\nYou are advised not to send any confidential and/or important information to the Bank via e-mail \n\n  \"The Personal Data Protection Act 2010 has been enforced on 15 December 2013. Please read our Privacy Notice which can be found at https://www.maybank.com/en/privacy-statement.page  or at any branch for details on how we process/protect your personal data.\"\n\n  This email and any of its attachments are confidential and may also be privileged. If you are not the intended recipient, please disregard the email and delete it immediately. Do not disclose, copy, circulate or in any other way, use or rely on the information contained in this email or its attachments. Email are not guaranteed to be secure or error-free as the message and any of its content could be intercepted, corrupted, lost, delayed, incomplete and amended. Please do not reply to this email.\"\n\n  If you do not wish to receive any promotional information from Maybank via email, unsubscribe here.','What you need to know before applying for business financing','1 Package',0.00,'NONE','masuk',1,'junk',NULL,'2026-09-01 04:38:53','2026-09-01 04:38:53'),
